from heapq import heappop, heappush

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_heap = []

    # Initialize the heap with all possible starting points
    for i in range(N):
        for j in range(N):
            heappush(min_heap, (grid[i][j], [(i, j)]))

    while min_heap:
        value, path = heappop(min_heap)
        if len(path) == k:
            return [grid[x][y] for x, y in path]

        x, y = path[-1]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heappush(min_heap, (value, path + [(nx, ny)]))
